1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns a newly created owner a {@code customerCode} formatted
11	 * {@code '<LAST3>-<NNNN>'}: LAST3 is the upper-cased first three letters of the
12	 * owner's last name and NNNN is a global 4-digit zero-padded sequence equal to
13	 * one more than the current number of owners. Runs before {@link SaveOwner} so
14	 * the owner being created is not yet counted. Mutates the {@link Owner} in place
15	 * so it is persisted and returned with the code.
16	 */
17	public class AssignOwnerCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String lastName = owner.getLastName();
21	        int len = Math.min(3, lastName.length());
22	        String last3 = lastName.substring(0, len).toUpperCase(Locale.ROOT);
23	        int sequence = ownerRepository.findAll().size() + 1;
24	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
25	    }
26	}
