18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /** Upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
29	    default String initials(Owner owner) {
30	        return owner.getFirstName().substring(0, 1).toUpperCase()
31	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
32	    }
33	
34	    /** Membership number '<customerCode>-M<YY>', YY = last two digits of the
35	     *  registrationDate year. Null unless both source fields are present. */
36	    default String membershipNumber(Owner owner) {
37	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
38	            return null;
39	        }
40	        return String.format("%s-M%02d", owner.getCustomerCode(),
41	                owner.getRegistrationDate().getYear() % 100);
42	    }
43	
44	    /** Membership tier: 'SILVER' when namesakeCount is 0 and an email is present,
45	     *  otherwise 'BRONZE'. */
46	    default String membershipTier(Owner owner) {
47	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
48	        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
49	        return (unique && hasEmail) ? "SILVER" : "BRONZE";
50	    }
