52	    Owner toOwner(OwnerDto ownerDto);
53	
54	    @Mapping(target = "id", ignore = true)
55	    @Mapping(target = "pets", ignore = true)
56	    Owner toOwner(OwnerFieldsDto ownerDto);
57	
58	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
59	
60	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
61	
62	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
63	        OwnerPageDto ownerPageDto = new OwnerPageDto();
